-- Total rows in a table:
SELECT COUNT(*) FROM customers;

-- Rows matching a condition:
SELECT COUNT(*) FROM orders WHERE status = 'shipped';

-- Non-NULL values in a column:
SELECT COUNT(email) FROM customers;   -- excludes NULL emails

-- Unique values:
SELECT COUNT(DISTINCT country) FROM customers;

-- Count per group:
SELECT status, COUNT(*) AS n
FROM orders
GROUP BY status;

-- MySQL: create and call
DELIMITER //
CREATE PROCEDURE GetOrdersForCustomer(IN cust_id INT)
BEGIN
    SELECT * FROM orders WHERE customer_id = cust_id;
END //
DELIMITER ;

CALL GetOrdersForCustomer(42);

-- PostgreSQL function (returns a value, usable in queries)
CREATE FUNCTION total_for_customer(cust_id INT) RETURNS NUMERIC AS $$
    SELECT SUM(amount) FROM orders WHERE customer_id = cust_id;
$$ LANGUAGE SQL;

SELECT total_for_customer(42);
